<?php
require_once __DIR__ . '/../config/Database.php'; require_once __DIR__ . '/JurnalKas.php';
class Penyaluran {
 private PDO $db; public function __construct(){ $this->db=Database::connect(); $this->db->exec("INSERT IGNORE INTO asnaf(nama) VALUES ('Fakir'),('Miskin'),('Sumbangan')"); }
 public function getAsnaf():array{return $this->db->query("SELECT id,nama FROM asnaf WHERE nama IN ('Fakir','Miskin','Sumbangan') ORDER BY FIELD(nama,'Fakir','Miskin','Sumbangan')")->fetchAll();}
 public function getAll(): array{return $this->db->query('SELECT s.*,m.nama AS mustahik,a.nama AS asnaf FROM penyaluran s JOIN mustahik m ON m.id=s.mustahik_id JOIN asnaf a ON a.id=m.asnaf_id ORDER BY s.tanggal DESC,s.id DESC')->fetchAll();}
 public function getById(int $id){$s=$this->db->prepare('SELECT s.*,m.nama AS mustahik,m.asnaf_id,a.nama AS asnaf FROM penyaluran s JOIN mustahik m ON m.id=s.mustahik_id JOIN asnaf a ON a.id=m.asnaf_id WHERE s.id=?');$s->execute([$id]);return $s->fetch();}
 private function mustahikId(string $nama,string $asnafNama):int{$nama=trim($nama);if($nama==='')throw new RuntimeException('Nama mustahik wajib diisi.');if(!in_array($asnafNama,['Fakir','Miskin','Sumbangan'],true))throw new RuntimeException('Asnaf tidak valid.');$q=$this->db->prepare('SELECT id FROM asnaf WHERE nama=? LIMIT 1');$q->execute([$asnafNama]);$asnaf=(int)$q->fetchColumn();if(!$asnaf){$q=$this->db->prepare('INSERT INTO asnaf(nama) VALUES(?)');$q->execute([$asnafNama]);$asnaf=(int)$this->db->lastInsertId();}$s=$this->db->prepare('SELECT id FROM mustahik WHERE LOWER(nama)=LOWER(?) LIMIT 1');$s->execute([$nama]);$id=$s->fetchColumn();if($id){$id=(int)$id;$u=$this->db->prepare('UPDATE mustahik SET asnaf_id=? WHERE id=?');$u->execute([$asnaf,$id]);return $id;}$last=(int)$this->db->query("SELECT COALESCE(MAX(CAST(SUBSTRING(kode,5) AS UNSIGNED)),0) FROM mustahik WHERE kode REGEXP '^MST-[0-9]+$'")->fetchColumn();$kode='MST-'.str_pad((string)($last+1),3,'0',STR_PAD_LEFT);$s=$this->db->prepare('INSERT INTO mustahik(kode,nama,asnaf_id) VALUES(?,?,?)');$s->execute([$kode,$nama,$asnaf]);return (int)$this->db->lastInsertId();}
 public function create(array $d): int{$this->db->beginTransaction();try{$mid=$this->mustahikId($d['nama_mustahik'],$d['asnaf']);$prefix='BKS-'.date('Y',strtotime($d['tanggal'])).'-';$q=$this->db->prepare('SELECT no_bukti FROM penyaluran WHERE no_bukti LIKE ? ORDER BY id DESC LIMIT 1');$q->execute([$prefix.'%']);$last=$q->fetchColumn();$no=$prefix.str_pad((string)($last?(int)substr($last,-4)+1:1),4,'0',STR_PAD_LEFT);$s=$this->db->prepare('INSERT INTO penyaluran(no_bukti,tanggal,mustahik_id,pos_dana,nominal,keterangan) VALUES(?,?,?,?,?,?)');$s->execute([$no,$d['tanggal'],$mid,$d['pos_dana'],$d['nominal'],$d['keterangan']]);$id=(int)$this->db->lastInsertId();(new JurnalKas())->catat(['tanggal'=>$d['tanggal'],'jenis'=>'keluar','pos_dana'=>$d['pos_dana'],'nominal'=>$d['nominal'],'keterangan'=>'Penyaluran '.$no.($d['keterangan']?' - '.$d['keterangan']:''),'sumber'=>'penyaluran','ref_id'=>$id]);$this->db->commit();return $id;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function update(int $id,array $d):void{$this->db->beginTransaction();try{$old=$this->getById($id);if(!$old)throw new RuntimeException('Penyaluran tidak ditemukan.');$mid=$this->mustahikId($d['nama_mustahik'],$d['asnaf']);$s=$this->db->prepare('UPDATE penyaluran SET tanggal=?,mustahik_id=?,pos_dana=?,nominal=?,keterangan=? WHERE id=?');$s->execute([$d['tanggal'],$mid,$d['pos_dana'],$d['nominal'],$d['keterangan'],$id]);$ket='Penyaluran '.$old['no_bukti'].($d['keterangan']?' - '.$d['keterangan']:'');$find=$this->db->prepare("SELECT id FROM jurnal_kas WHERE sumber='penyaluran' AND ref_id=? ORDER BY id DESC LIMIT 1");$find->execute([$id]);$journalId=$find->fetchColumn();if($journalId){$s=$this->db->prepare("UPDATE jurnal_kas SET tanggal=?,pos_dana=?,nominal=?,keterangan=?,jenis='keluar' WHERE sumber='penyaluran' AND ref_id=?");$s->execute([$d['tanggal'],$d['pos_dana'],$d['nominal'],$ket,$id]);}else{(new JurnalKas())->catat(['tanggal'=>$d['tanggal'],'jenis'=>'keluar','pos_dana'=>$d['pos_dana'],'nominal'=>$d['nominal'],'keterangan'=>$ket,'sumber'=>'penyaluran','ref_id'=>$id]);}$this->checkBalances();$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function delete(int $id):void{$this->db->beginTransaction();try{$old=$this->getById($id);if(!$old)throw new RuntimeException('Penyaluran tidak ditemukan.');$this->db->prepare("DELETE FROM jurnal_kas WHERE sumber='penyaluran' AND ref_id=?")->execute([$id]);$this->db->prepare('DELETE FROM penyaluran WHERE id=?')->execute([$id]);$this->checkBalances();$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 private function checkBalances():void{foreach(JurnalKas::POS as $pos=>$name){$s=$this->db->prepare("SELECT COALESCE(SUM(CASE WHEN jenis='masuk' THEN nominal ELSE -nominal END),0) FROM jurnal_kas WHERE pos_dana=?");$s->execute([$pos]);if((float)$s->fetchColumn()<0)throw new RuntimeException('Saldo '.$name.' tidak mencukupi.');}}
}
